package com.thralltracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.*;

@ConfigGroup("thralldamagetracker")
public interface ThrallDamageTrackerConfig extends Config {
    @ConfigItem(keyName = "resetOnNewTarget", name = "Reset on New Target", description = "Reset stats when switching NPCs", position = 1)
    default boolean resetOnNewTarget() {
        return true;
    }

    @ConfigItem(keyName = "fontSize", name = "Font Size", description = "Size of text in panel", position = 2)
    default int fontSize() {
        return 12;
    }

    @ConfigItem(keyName = "npcNameColour", name = "NPC Name Colour", description = "Colour of the target name", position = 3)
    default Color npcNameColour() {
        return Color.WHITE;
    }

    @ConfigItem(keyName = "damageColour", name = "Damage Colour", description = "Colour of the damage value", position = 4)
    default Color damageColour() {
        return Color.RED;
    }

    @ConfigItem(
            keyName = "thrallLifespan",
            name = "Thrall Lifespan (seconds)",
            description = "How long your thralls last (60, 90, or 120)",
            position = 5
    )
    default int thrallLifespan() {
        return 60;
    }
}

package com.thralltracker;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;

public class ThrallDamageTrackerOverlay extends OverlayPanel {
    private final ThrallDamageTrackerPlugin plugin;

    @Inject
    private ThrallDamageTrackerOverlay(ThrallDamageTrackerPlugin plugin) {
        super(plugin);
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        int damage = plugin.getThrallDamage();
        int remaining = plugin.getSecondsRemaining();

        if (remaining <= 0 && damage <= 0) return null;

        panelComponent.getChildren().clear();

        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Thrall Tracker")
                .build());

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Damage:")
                .right(Integer.toString(damage))
                .build());

        // Time Remaining with Dynamic Colour
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Time:")
                .right(remaining + "s")
                .rightColor(getTimerColor(remaining)) // This sets the text colour
                .build());

        return super.render(graphics);
    }

    private Color getTimerColor(int secondsLeft) {
        if (secondsLeft <= 10) return Color.RED;
        if (secondsLeft <= 20) return Color.YELLOW;
        return Color.GREEN;
    }
}

package com.thralltracker;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class ThrallDamageTrackerPanel extends PluginPanel {
    private final ThrallDamageTrackerPlugin plugin;
    private final ThrallDamageTrackerConfig config;
    private final JLabel npcNameLabel;
    private final JLabel damageValueLabel;
    private final JLabel durationValueLabel;
    private final JLabel statusLabel;

    public ThrallDamageTrackerPanel(ThrallDamageTrackerPlugin plugin, ThrallDamageTrackerConfig config) {
        super();
        this.plugin = plugin;
        this.config = config;

        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setLayout(new BorderLayout(0, 10));
        setBorder(new EmptyBorder(10, 10, 10, 10));

        JLabel titleLabel = new JLabel("Thrall Damage Tracker", SwingConstants.CENTER);
        titleLabel.setForeground(Color.WHITE);
        titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 15f));

        JPanel statsCard = new JPanel(new GridBagLayout());
        statsCard.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        statsCard.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 1),
                new EmptyBorder(12, 14, 12, 14)
        ));

        GridBagConstraints c = new GridBagConstraints();
        c.fill = GridBagConstraints.HORIZONTAL;
        c.insets = new Insets(4, 0, 4, 0);

        npcNameLabel = new JLabel("No target", SwingConstants.CENTER);
        c.gridy = 0;
        c.gridwidth = 2;
        statsCard.add(npcNameLabel, c);

        damageValueLabel = new JLabel("0", SwingConstants.RIGHT);
        c.gridy = 1;
        c.gridwidth = 1;
        statsCard.add(new JLabel("Damage:"), c);
        c.gridx = 1;
        statsCard.add(damageValueLabel, c);

        durationValueLabel = new JLabel("0s", SwingConstants.RIGHT);
        c.gridx = 0;
        c.gridy = 2;
        statsCard.add(new JLabel("Time:"), c);
        c.gridx = 1;
        statsCard.add(durationValueLabel, c);

        statusLabel = new JLabel("Waiting for thrall...", SwingConstants.CENTER);
        statusLabel.setFont(statusLabel.getFont().deriveFont(Font.ITALIC, 11f));

        JButton resetButton = new JButton("RESET SESSION");
        resetButton.setBackground(new Color(180, 40, 40));
        resetButton.setForeground(Color.WHITE);
        resetButton.addActionListener(e -> plugin.resetTracking());

        add(titleLabel, BorderLayout.NORTH);
        add(statsCard, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new GridLayout(2, 1, 0, 5));
        bottom.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bottom.add(statusLabel);
        bottom.add(resetButton);
        add(bottom, BorderLayout.SOUTH);

        applyConfig();
    }

    public void applyConfig() {
        npcNameLabel.setFont(npcNameLabel.getFont().deriveFont(Font.BOLD, (float) config.fontSize() + 2));
        npcNameLabel.setForeground(config.npcNameColour());
        damageValueLabel.setForeground(config.damageColour());
    }

    public void updateDisplay(String npcName, int damage, long seconds) {
        SwingUtilities.invokeLater(() -> {
            int remaining = plugin.getSecondsRemaining();

            npcNameLabel.setText(npcName != null ? npcName : "No target");
            damageValueLabel.setText(String.valueOf(damage));

            durationValueLabel.setText(remaining + "s");
            durationValueLabel.setForeground(getTimerColor(remaining));

            statusLabel.setText(remaining > 0 ? "Thrall Active" : "Thrall Expired");
            statusLabel.setForeground(remaining > 10 ? Color.GREEN : Color.RED);

            revalidate();
            repaint();
        });
    }

    private Color getTimerColor(int secondsLeft) {
        if (secondsLeft <= 10) return Color.RED;
        if (secondsLeft <= 20) return Color.YELLOW;
        return Color.WHITE;
    }
}

package com.thralltracker;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;

@Slf4j
@PluginDescriptor(
        name = "Thrall Damage Tracker",
        description = "Tracks damage dealt by your thralls",
        tags = {"combat", "thrall", "tracker", "arceuus"}
)
public class ThrallDamageTrackerPlugin extends Plugin {
    private static final Set<Integer> THRALL_IDS = new HashSet<>();

    static {
        for (int i = 10880; i <= 10888; i++) THRALL_IDS.add(i); // Ghost, Skeleton, Zombie (All tiers)
    }

    @Inject
    private Client client;
    @Inject
    private ClientToolbar clientToolbar;
    @Inject
    private ThrallDamageTrackerConfig config;
    @Inject
    private ThrallDamageTrackerOverlay overlay;
    @Inject
    private net.runelite.client.ui.overlay.OverlayManager overlayManager;

    public int getThrallDamage() {
        return thrallDamage;
    }

    private ThrallDamageTrackerPanel panel;
    private NavigationButton navButton;

    private NPC currentTargetNpc = null;
    private int thrallDamage = 0;
    private long trackingStartMs = 0;
    private final Set<NPC> myThralls = new HashSet<>();

    @Override
    protected void startUp() throws Exception {
        panel = new ThrallDamageTrackerPanel(this, config);
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

        navButton = NavigationButton.builder()
                .tooltip("Thrall Damage Tracker")
                .icon(icon)
                .priority(6)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown() {
        clientToolbar.removeNavigation(navButton);
        myThralls.clear();
        resetState();
        overlayManager.remove(overlay);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        if (event.getMessage().contains("You resurrect")) {
            // Reset ONLY the timer
            trackingStartMs = System.currentTimeMillis();
            updateUI();
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        // If the timer isn't running, we aren't tracking
        if (trackingStartMs == 0) return;

        Hitsplat hitsplat = event.getHitsplat();
        int type = hitsplat.getHitsplatType();

        // 16 = Cyan Me, 17 = Cyan Other (Standard Thrall IDs)
        if (type == 16 || type == 17) {
            if (!(event.getActor() instanceof NPC)) return;
            NPC target = (NPC) event.getActor();

            // Update target name if it changed or is new
            if (currentTargetNpc == null || currentTargetNpc != target) {
                currentTargetNpc = target;
            }

            // Add the damage
            thrallDamage += hitsplat.getAmount();
            updateUI();

            log.info("Thrall hit {} for {}! Total: {}", target.getName(), hitsplat.getAmount(), thrallDamage);
        }
    }


    public int getSecondsRemaining() {
        if (trackingStartMs == 0) return 0;

        long elapsed = (System.currentTimeMillis() - trackingStartMs) / 1000;
        int remaining = config.thrallLifespan() - (int) elapsed;

        return Math.max(0, remaining);
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        myThralls.remove(event.getNpc());
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event) {
        NPC npc = event.getNpc();
        if (THRALL_IDS.contains(npc.getId())) {
            myThralls.add(npc);
            log.info("FOUND THRALL: {} (Index: {})", npc.getName(), npc.getIndex());
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        // If a session is active (timer > 0), refresh the UI every 0.6s
        if (trackingStartMs != 0) {
            updateUI();


            if (getSecondsRemaining() <= 0) {
                log.info("Thrall lifespan reached.");
            }
        }
    }

    private void updateUI() {
        if (panel != null) {
            String name = currentTargetNpc != null ? currentTargetNpc.getName() : "None";
            panel.updateDisplay(name, thrallDamage, getElapsedSeconds());
        }
    }

    public long getElapsedSeconds() {
        return trackingStartMs == 0 ? 0 : (System.currentTimeMillis() - trackingStartMs) / 1000;
    }

    private void resetState() {
        thrallDamage = 0;
        trackingStartMs = 0;
        currentTargetNpc = null;
        updateUI();
    }

    @Provides
    ThrallDamageTrackerConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(ThrallDamageTrackerConfig.class);
    }

    public void resetTracking() {
        thrallDamage = 0;
        trackingStartMs = 0;
        currentTargetNpc = null;
        updateUI();
    }
}
